// Растр: прозрачность 0..15, 4 бита на пиксель, старший полубайт — левый пиксель, строка глифа выровнена на байт.
#pragma once
#include <stdint.h>

struct SmoothGlyph {
    uint32_t offset;   // начало растра в bitmap
    uint8_t  w, h;     // размер растра, px
    int8_t   dx;       // левый край растра относительно пера, px
    uint8_t  dy;       // верх растра относительно верха строки, px
    uint8_t  adv;      // сдвиг пера, px
};

struct SmoothFont {
    uint8_t            h;        // высота строки (объединённая рамка цифр), px
    const SmoothGlyph* glyphs;   // в порядке SMOOTH_DIGITS_CHARS
    const uint8_t*     bitmap;
};

constexpr uint8_t SMOOTH_DIGITS_ALPHA_MAX   = 15;   // непрозрачный пиксель
constexpr uint8_t SMOOTH_DIGITS_SMALL_CHARS = 4;    // любые столько знаков мелким размером влезают в 312 px
static const char SMOOTH_DIGITS_CHARS[] = "-0123456789";   // порядок глифов

